        java.lang.StringBuilder sb = new java.lang.StringBuilder("RenderScript yuvToRgb. Non-even dimensions are not supported. ");
        sb.append(sizeX);
        sb.append(" and ");
        sb.append(sizeY);
        sb.append(" were provided.");
